void invoke(ui::Editor& editor,const wchar_t* name){editor.update();UpdateWindow(editor.hwnd());win::ComPtr<IAccessible> tree;check(SUCCEEDED(AccessibleObjectFromWindow(editor.hwnd(),static_cast<DWORD>(OBJID_CLIENT),IID_PPV_ARGS(&tree))),"Studio accessibility missing");long count=0;tree->get_accChildCount(&count);for(long n=1;n<=count;++n){VARIANT id{};id.vt=VT_I4;id.lVal=n;BSTR text=nullptr;tree->get_accName(id,&text);bool found=text&&std::wstring_view(text)==name;SysFreeString(text);if(found){check(SUCCEEDED(tree->accSelect(SELFLAG_TAKEFOCUS,id)),"Control focus failed");UpdateWindow(editor.hwnd());SendMessageW(editor.hwnd(),WM_KEYDOWN,VK_RETURN,0);UpdateWindow(editor.hwnd());return;}}throw std::runtime_error("Expected Studio control absent");}
HWND widget(){HWND found=nullptr;EnumThreadWindows(GetCurrentThreadId(),[](HWND h,LPARAM p)->BOOL{if(win::windowText(h).starts_with(L"Aether extension:")){*reinterpret_cast<HWND*>(p)=h;return FALSE;}return TRUE;},reinterpret_cast<LPARAM>(&found));return found;}
